// Twilio envía los datos de WhatsApp como form data
const body = $input.first().json.body || $input.first().json;

// Mensaje entrante de WhatsApp
const rawMessage = body.Body || '';
const fromNumber = (body.From || '').replace('whatsapp:', '');

// Parsear el mensaje - ajustar según formato real de pedidos
// Formato esperado: "Pedido de [Nombre]\n[Dirección]\n[Método pago]\nTotal: $[monto]"
const lines = rawMessage.split('\n').map(l => l.trim()).filter(Boolean);

let nombre_cliente = 'Cliente Domicilio';
let direccion = null;
let metodo_pago = null;
let monto_total = null;

// Intentar extraer nombre
const nameMatch = rawMessage.match(/(?:pedido de|nombre:?)\s*(.+)/i);
if (nameMatch) {
  nombre_cliente = nameMatch[1].trim();
} else if (lines.length > 0) {
  nombre_cliente = lines[0];
}

// Intentar extraer dirección
const addrMatch = rawMessage.match(/(?:direcci[oó]n:?|dir:?)\s*(.+)/i);
if (addrMatch) {
  direccion = addrMatch[1].trim();
} else if (lines.length > 1) {
  direccion = lines[1];
}

// Intentar extraer método de pago
const payMatch = rawMessage.match(/(?:pago:?|m[eé]todo:?)\s*(.+)/i);
if (payMatch) {
  metodo_pago = payMatch[1].trim();
}

// Intentar extraer monto
const amountMatch = rawMessage.match(/(?:total:?|\$)\s*([\d.,]+)/i);
if (amountMatch) {
  monto_total = parseFloat(amountMatch[1].replace(/[.,]/g, ''));
}

return [{
  json: {
    nombre_cliente,
    celular: fromNumber,
    direccion,
    metodo_pago,
    monto_total,
    raw_message: rawMessage
  }
}];
